// План specs/billing-granted-plan.md, 2.1. Две роли: admin назначает Starter Tech — «בדיקה» видит на Billing текст без trial.
// ПИШЕТ данные на проде: только «בדיקה», revokeIfAssigned до и в finally. Не @prod-safe.
import { test, expect } from '../../fixtures';
import { setLanguage, targetRow, openPlansTab, revokeIfAssigned, enDate } from '../admin-plans/plans-helpers';
import { REASON, UNTIL_DAYS, PROPAGATION_MS, TRIAL_TEXT, grantedTextEn, addPaymentButton, assignPlan } from './granted-helpers';

test.describe.configure({ mode: 'serial' });

test.describe('Billing — granted plan seen by the user', () => {
  test('Granted Starter Tech replaces the trial text with "no card is needed until <date>", revoke restores the previous text #550e01db @desktop @writes', async ({ asUser }) => {
    test.setTimeout(420_000);
    const admin = await asUser('admin');
    const user = await asUser('user');
    await setLanguage(admin, 'en');
    await setLanguage(user, 'en');

    await revokeIfAssigned(admin, `${REASON} pre-clean`);

    try {
      // 1. Состояние «до»
      await user.goto('/BillingSubscription');
      await expect(user.getByText('Payment method', { exact: true }).first()).toBeVisible();
      await expect(user.getByText(/granted by Techory/i)).toHaveCount(0);
      const trialBefore = await user.getByText(TRIAL_TEXT).isVisible();

      // 2. Admin назначает Starter Tech
      await assignPlan(admin, 'Starter Tech');

      // 3. У пользователя без перезагрузки — granted-текст, без trial
      const date = enDate(UNTIL_DAYS);
      const granted = user.getByText(grantedTextEn(date));
      await expect(granted).toBeVisible({ timeout: PROPAGATION_MS });
      await expect(user.getByText(`Granted by Techory until ${date}`, { exact: true })).toBeVisible();
      await expect(user.getByText(/after the trial/i)).toHaveCount(0);
      await expect(granted.locator('xpath=..')).not.toContainText(/trial/i);
      await expect(addPaymentButton(user).first()).toBeVisible();

      // 4. Admin отменяет
      await revokeIfAssigned(admin, REASON);
      const row = await targetRow(admin);
      await expect(row.getByRole('button', { name: 'Assign plan', exact: true })).toBeVisible();
      await expect(row.getByRole('button', { name: 'Revoke', exact: true })).toHaveCount(0);

      // 5. У пользователя без перезагрузки — прежний текст
      await expect(user.getByText(/granted by Techory/i)).toHaveCount(0, { timeout: PROPAGATION_MS });
      if (trialBefore) {
        await expect(user.getByText(TRIAL_TEXT)).toBeVisible();
        await openPlansTab(admin);
        const rowAfter = await targetRow(admin);
        await expect(rowAfter).toContainText('Starter Tech Trial');
        await expect(rowAfter).toContainText('Trial');
      }
    } finally {
      await revokeIfAssigned(admin, `${REASON} cleanup`);
    }
  });
});
